
import React, { useState } from 'react';

function Mfaq() {
  const [openItem, setOpenItem] = useState(0);

  const questions = [
    {
      question: 'Can I change my membership plan later?',
      answer:
        'Yes. You can request to upgrade or change your membership plan. Any price difference and the date when the new plan takes effect will depend on the membership terms.'
    },
    {
      question: 'Can I freeze or pause my membership?',
      answer:
        'Membership freezing may be available in certain situations. Please contact our team to check the eligibility requirements, available options, and any applicable fees.'
    },
    {
      question: 'Do I need to be experienced to join FORGE FITNESS?',
      answer:
        'Not at all. Beginners are welcome. Start with a plan that matches your current fitness level, learn the correct exercise techniques, and increase the intensity gradually as you progress.'
    },
    {
      question: 'Are personal training sessions available?',
      answer:
        'Personal training can help you work toward specific goals with a more structured approach. Contact our team to ask about trainer availability, session options, and pricing.'
    },
    {
      question: 'Can I try the gym before choosing a membership?',
      answer:
        'You can contact our team to ask whether a trial session or gym tour is available. We recommend checking the current options before purchasing a membership.'
    },
    {
      question: 'What payment methods can I use?',
      answer:
        'Available payment methods may vary depending on the membership and current gym policies. Please contact our team to confirm accepted payment methods and the total cost before completing your registration.'
    }
  ];

  return (
    <div className="membership-page">
      <section
        id="faq-section"
        className="section-padding section-light"
        aria-labelledby="faq-title"
      >
        <div className="container">
          <div className="section-heading text-center mx-auto">
            <p className="section-eyebrow">FAQ</p>

            <h2 className="section-title" id="faq-title">
              Common Questions
            </h2>
          </div>

          <div className="row">
            <div className="col-lg-8 mx-auto">
              <div className="accordion faq-accordion" id="faqAccordion">
                {questions.map((item, index) => (
                  <div className="accordion-item" key={item.question}>
                    <h3 className="accordion-header">
                      <button
                        className={`accordion-button ${
                          openItem === index ? '' : 'collapsed'
                        }`}
                        type="button"
                        aria-expanded={openItem === index}
                        aria-controls={`faq-answer-${index}`}
                        onClick={() =>
                          setOpenItem(
                            openItem === index ? -1 : index
                          )
                        }
                      >
                        {item.question}
                      </button>
                    </h3>

                    <div
                      id={`faq-answer-${index}`}
                      className={`faq-collapse ${
                        openItem === index ? 'open' : ''
                      }`}
                    >
                      <div className="accordion-body">
                        {item.answer}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}

export default Mfaq;
