import React from 'react'

function Mplans() {
  return (
    <div><>
  {/* ===== MEMBERSHIP PLANS SECTION START ===== */}
  <section
    id="plans-section"
    className="section-padding section-light"
    aria-labelledby="plans-title"
  >
    <div className="container">
      <div className="section-heading text-center mx-auto">
        <p className="section-eyebrow">Plans</p>
        <h2 className="section-title" id="plans-title">
          Compare Plans
        </h2>
        <p className="section-subtitle">
          Three simple plans, billed monthly. Choose one to continue to the
          application form.
        </p>
      </div>
      <div className="row g-4 justify-content-center">
        <div className="col-md-8 col-lg-4">
          <article className="forge-card membership-card">
            <h3 className="membership-tier">Basic</h3>
            <p className="membership-price">
              <span className="membership-currency">EGP</span>500
              <span className="membership-period">/month</span>
            </p>
            <p className="membership-billing">Billed monthly. Example price.</p>
            <ul className="membership-features">
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Access to gym facilities
              </li>
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Standard equipment access
              </li>
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Flexible monthly membership
              </li>
            </ul>
            <a
              className="btn btn-forge-outline"
              href="/Subscribe"
              data-plan-name="Basic"
              data-plan-price={500}
              data-plan-currency="EGP"
              data-plan-period="month"
            >
              CHOOSE PLAN<span className="visually-hidden"> Basic</span>
            </a>
          </article>
        </div>
        <div className="col-md-8 col-lg-4">
          <article className="forge-card forge-card-dark membership-card">
            <span className="membership-badge">Most Popular</span>
            <h3 className="membership-tier">Pro</h3>
            <p className="membership-price">
              <span className="membership-currency">EGP</span>800
              <span className="membership-period">/month</span>
            </p>
            <p className="membership-billing">Billed monthly. Example price.</p>
            <ul className="membership-features">
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Everything in Basic
              </li>
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Group training sessions
              </li>
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Personalized workout guidance
              </li>
            </ul>
            <a
              className="btn btn-forge-light"
               href="/Subscribe"
              data-plan-name="Pro"
              data-plan-price={800}
              data-plan-currency="EGP"
              data-plan-period="month"
            >
              CHOOSE PLAN<span className="visually-hidden"> Pro</span>
            </a>
          </article>
        </div>
        <div className="col-md-8 col-lg-4">
          <article className="forge-card membership-card">
            <h3 className="membership-tier">Elite</h3>
            <p className="membership-price">
              <span className="membership-currency">EGP</span>1,200
              <span className="membership-period">/month</span>
            </p>
            <p className="membership-billing">Billed monthly. Example price.</p>
            <ul className="membership-features">
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Everything in Pro
              </li>
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Personal training sessions
              </li>
              <li>
                <i className="bi bi-check2" aria-hidden="true" />
                Priority booking
              </li>
            </ul>
            <a
              className="btn btn-forge-outline"
              href="/Subscribe"
              data-plan-name="Elite"
              data-plan-price={1200}
              data-plan-currency="EGP"
              data-plan-period="month"
            >
              CHOOSE PLAN<span className="visually-hidden"> Elite</span>
            </a>
          </article>
        </div>
      </div>
      <p className="section-note">
        Prices and benefits are illustrative placeholders for a university
        project, not real gym offers.
      </p>
    </div>
  </section>
  {/* ===== MEMBERSHIP PLANS SECTION END ===== */}
</>
</div>
  )
}

export default Mplans