
import React, { useState } from 'react';

function Tgrid() {
  const [selectedTrainer, setSelectedTrainer] = useState(null);
  const [modalVisible, setModalVisible] = useState(false);

  const trainers = [
    {
      name: 'Alex Rowan',
      role: 'Strength & Conditioning',
      image: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=700&q=70',
      bio: 'Alex coaches barbell technique and progressive overload for lifters of every level. Expect clear form cues, structured weekly plans and a steady focus on getting stronger safely.'
    },
    {
      name: 'Maya Hale',
      role: 'Cardio & Endurance',
      image: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=700&q=70',
      bio: 'Maya builds stamina through running, rowing and interval work. She helps members pace themselves, improve heart health and finish their first 5K with confidence.'
    },
    {
      name: 'Sam Ortega',
      role: 'Weight Management & Nutrition',
      image: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=700&q=70',
      bio: 'Sam combines practical training with simple, sustainable eating habits. His approach is built around realistic goals, regular check-ins and steady fat loss.'
    },
    {
      name: 'Jordan Blake',
      role: 'Personal Training',
      image: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=700&q=70',
      bio: 'Jordan designs one-to-one sessions around your goals, schedule and experience. Every workout is tailored, tracked and adjusted so you always know what comes next.'
    },
    {
      name: 'Chloe Bennett',
      role: 'Functional Fitness & Mobility',
      image: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=700&q=70',
      bio: 'Chloe focuses on movement quality, balance and flexibility. Her sessions help you move better in daily life, recover faster and reduce the risk of injury.'
    },
    {
      name: 'Marcus Reed',
      role: 'Bodybuilding & Muscle Growth',
      image: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=700&q=70',
      bio: 'Marcus specialises in hypertrophy training, split routines and muscle-building nutrition. He guides members through every phase from bulking to cutting.'
    }
  ];

  function openModal(trainer) {
    setSelectedTrainer(trainer);
    setModalVisible(false);

    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        setModalVisible(true);
      });
    });
  }

  function closeModal() {
    setModalVisible(false);

    setTimeout(() => {
      setSelectedTrainer(null);
    }, 300);
  }

  return (
    <div className="trainers-page">

      {/* ===== TRAINERS GRID SECTION START ===== */}
      <section
        id="trainers-section"
        className="section-padding"
        aria-labelledby="trainers-title"
      >
        <div className="container">

          <div className="section-heading text-center mx-auto">
            <p className="section-eyebrow">Trainers</p>

            <h2 className="section-title" id="trainers-title">
              Our Trainers
            </h2>

            <p className="section-subtitle">
              Six specialists for different goals. Open any card to read more.
            </p>
          </div>

          <div className="row g-4" id="trainersGrid">
            {trainers.map((trainer) => (
              <div className="col-sm-6 col-lg-4" key={trainer.name}>
                <article className="forge-card trainer-card">

                  <div className="trainer-photo">
                    <button
                      type="button"
                      className="trainer-image-button"
                      onClick={() => openModal(trainer)}
                      aria-label={`View ${trainer.name}'s details`}
                    >
                      <img
                        src={trainer.image}
                        alt={trainer.name}
                        className="img-fallback"
                        loading="lazy"
                      />
                    </button>
                  </div>

                  <div className="trainer-body">
                    <h3 className="trainer-name">
                      <button
                        type="button"
                        className="trainer-open"
                        onClick={() => openModal(trainer)}
                      >
                        {trainer.name}
                      </button>
                    </h3>

                    <p className="trainer-role">
                      {trainer.role}
                    </p>
                  </div>

                </article>
              </div>
            ))}
          </div>

          <p className="section-note">
            Demo content: trainer names, specializations, descriptions and photos are placeholders.
          </p>

        </div>
      </section>
      {/* ===== TRAINERS GRID SECTION END ===== */}

      {/* ===== TRAINER DETAILS MODAL START ===== */}
      {selectedTrainer && (
        <>
          <div
            className={`modal fade ${modalVisible ? 'show' : ''}`}
            style={{
              display: 'block',
              pointerEvents: modalVisible ? 'auto' : 'none'
            }}
            tabIndex="-1"
            role="dialog"
            aria-modal="true"
            aria-labelledby="trainerModalTitle"
            onClick={(event) => {
              if (event.target === event.currentTarget) {
                closeModal();
              }
            }}
          >
            <div className="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable">
              <div className="modal-content trainer-modal">

                <div className="modal-header">
                  <h2 className="modal-title" id="trainerModalTitle">
                    {selectedTrainer.name}
                  </h2>

                  <button
                    type="button"
                    className="btn-close"
                    aria-label="Close"
                    onClick={closeModal}
                  />
                </div>

                <div className="modal-body">
                  <div className="row g-4">

                    <div className="col-md-5">
                      <div className="trainer-modal-media">
                        <img
                          src={selectedTrainer.image}
                          alt={selectedTrainer.name}
                          className="img-fallback"
                        />
                      </div>
                    </div>

                    <div className="col-md-7">
                      <p className="trainer-modal-role">
                        {selectedTrainer.role}
                      </p>

                      <p>{selectedTrainer.bio}</p>
                    </div>

                  </div>
                </div>

                <div className="modal-footer">
                  <button
                    type="button"
                    className="btn btn-forge-outline btn-forge-sm"
                    onClick={closeModal}
                  >
                    CLOSE
                  </button>

                  <a
                    className="btn btn-forge-outline btn-forge-sm"
                    href="/"
                  >
                    BACK TO HOME
                  </a>

                  <a
                    className="btn btn-forge-dark btn-forge-sm"
                    href="/memberships"
                  >
                    VIEW MEMBERSHIPS
                  </a>
                </div>

              </div>
            </div>
          </div>

          <div
            className={`modal-backdrop fade ${modalVisible ? 'show' : ''}`}
            onClick={closeModal}
          />
        </>
      )}
      {/* ===== TRAINER DETAILS MODAL END ===== */}

    </div>
  );
}

export default Tgrid;
