import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { createBrowserRouter ,RouterProvider } from 'react-router';
import { AllData } from './Data/AllData';
import AllCart from './cart/AllCart';
import ScrollToTop from 'react-scroll-to-top';
import AllPrograms from './Programs/AllPrograms';
import AllTrainers from './Trainers/AllTrainers';
import AllMemberships from './Memberships/AllMemberships';
import ALLAbout from './About/ALLAbout';
import ALLProducts from './Products/AllProducts';
import { CartProvider } from 'react-use-cart';
import AllSubscribe from './Subscribe/AllSubscribe';


var ahmed = createBrowserRouter([
  {
    path:"/",
    element :<App/>,
  },
  {
    path:"programs",
    element :<AllPrograms/>,
  },
  {
    path:"Trainers",
    element :<AllTrainers/>,
  },
  
  {
    path:"Memberships",
    element :<AllMemberships/>,
  },
  {
    path:"Products",
    element :<ALLProducts/>,
  },
  {
    path:"About",
    element :<ALLAbout/>,
  },
  {
    path:"cart",
    element :<AllCart/>,
  },
  {
    path:"Subscribe",
    element :<AllSubscribe/>,
  },
 
]);


const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <AllData>
    <CartProvider>
       <ScrollToTop/>
       <RouterProvider router={ahmed}/>
    </CartProvider>
  </AllData>
  
);


