import React from 'react'

function Dprog() {
  return (
    <div><>
  {/* ===== PROGRAM DETAILS MODAL SECTION START ===== */}
  <div
    className="modal fade scroll-reveal"
    id="programModal"
    tabIndex={-1}
    aria-labelledby="programModalTitle"
    aria-hidden="true"
  >
    <div className="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable">
      <div className="modal-content program-modal">
        <div className="modal-header">
          <h2 className="modal-title" id="programModalTitle">
            Program details
          </h2>
          <button
            type="button"
            className="btn-close"
            data-bs-dismiss="modal"
            aria-label="Close"
          />
        </div>
        <div className="modal-body">
          <div className="row g-4">
            <div className="col-md-5">
              <div className="program-modal-media">
                <img
                  id="programModalImage"
                  className="img-fallback"
                  alt=""
                  hidden=""
                />
              </div>
            </div>
            <div className="col-md-7">
              <p className="program-modal-level">
                Level: <span id="programModalLevel" />
              </p>
              <div id="programModalDetails" />
            </div>
          </div>
        </div>
        <div className="modal-footer">
          <button
            type="button"
            className="btn btn-forge-outline btn-forge-sm"
            data-bs-dismiss="modal"
          >
            CLOSE
          </button>
          <a
            className="btn btn-forge-dark btn-forge-sm"
            href="/Memberships"
          >
            VIEW MEMBERSHIPS
          </a>
        </div>
      </div>
    </div>
  </div>
  {/* ===== PROGRAM DETAILS MODAL SECTION END ===== */}
</>
</div>
  )
}

export default Dprog