
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';

function AllSubscribe() {
  const navigate = useNavigate();

  const [selectedPlan, setSelectedPlan] = useState('Pro');

  const [fullName, setFullName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [age, setAge] = useState('');
  const [program, setProgram] = useState('');
  const [trainer, setTrainer] = useState('');

  const [message, setMessage] = useState('');
  const [seconds, setSeconds] = useState(5);

  const plans = [
    {
      name: 'Basic',
      price: 400,
      features: [
        'Full gym access',
        'Basic workout equipment',
        'Locker room access',
      ],
    },
    {
      name: 'Pro',
      price: 800,
      features: [
        'Everything in Basic',
        'Group training sessions',
        'Personalized workout guidance',
      ],
    },
    {
      name: 'Elite',
      price: 1200,
      features: [
        'Everything in Pro',
        'Personal trainer sessions',
        'Priority booking',
      ],
    },
  ];

  const currentPlan = plans.find(
    (plan) => plan.name === selectedPlan
  );

  function handleSubmit(event) {
    event.preventDefault();

    setMessage('success');
    setSeconds(5);
  }

  useEffect(() => {
    if (message !== 'success') {
      return;
    }

    const countdown = setInterval(() => {
      setSeconds((previousSeconds) =>
        previousSeconds > 0 ? previousSeconds - 1 : 0
      );
    }, 1000);

    const redirect = setTimeout(() => {
      navigate('/');
    }, 5000);

    return () => {
      clearInterval(countdown);
      clearTimeout(redirect);
    };
  }, [message, navigate]);

  return (
    <div className="subscribe-page">

      {message === 'success' ? (
        <div className="subscribe-success-page">
          <div className="subscribe-success" role="status">

            <div className="success-icon">
              <i className="bi bi-check-lg"></i>
            </div>

            <p className="subscribe-label">
              FORGE FITNESS
            </p>

            <h2>REQUEST SENT SUCCESSFULLY!</h2>

            <p>
              Your subscription request has been submitted.
              Our team will contact you soon.
            </p>

            <div className="success-plan">
              <span>SELECTED MEMBERSHIP</span>

              <strong>{currentPlan.name}</strong>

              <span>
                EGP {currentPlan.price} / month
              </span>
            </div>

            <p className="redirect-message">
              Redirecting to the home page in
            </p>

            <div className="countdown-number">
              {seconds}
            </div>

            <div className="countdown-track">
              <div className="countdown-progress"></div>
            </div>

          </div>
        </div>
      ) : (
        <>
          <Navbar />

          {/* START: Hero Section */}
          <section className="subscribe-hero">
            <div className="container">
              <p className="subscribe-label">
                MEMBERSHIP
              </p>

              <h1>JOIN FORGE FITNESS</h1>

              <p>
                Choose your plan and complete your
                subscription request.
              </p>
            </div>
          </section>
          {/* END: Hero Section */}

          <section className="subscribe-content container">
            <div className="row g-4">

              {/* START: Subscription Form */}
              <div className="col-lg-7">
                <div className="subscribe-card">

                  <h2>YOUR DETAILS</h2>

                  <form onSubmit={handleSubmit}>

                    <div className="mb-4">
                      <label className="form-label">
                        FULL NAME
                      </label>

                      <input
                        type="text"
                        className="form-control"
                        value={fullName}
                        onChange={(event) =>
                          setFullName(event.target.value)
                        }
                        required
                      />
                    </div>

                    <div className="mb-4">
                      <label className="form-label">
                        PHONE NUMBER
                      </label>

                      <input
                        type="tel"
                        className="form-control"
                        value={phone}
                        onChange={(event) =>
                          setPhone(event.target.value)
                        }
                        required
                      />
                    </div>

                    <div className="mb-4">
                      <label className="form-label">
                        EMAIL ADDRESS
                      </label>

                      <input
                        type="email"
                        className="form-control"
                        value={email}
                        onChange={(event) =>
                          setEmail(event.target.value)
                        }
                        required
                      />
                    </div>

                    <div className="mb-4">
                      <label className="form-label">
                        AGE
                      </label>

                      <input
                        type="number"
                        className="form-control"
                        min="14"
                        max="100"
                        value={age}
                        onChange={(event) =>
                          setAge(event.target.value)
                        }
                        required
                      />
                    </div>

                    <div className="mb-4">
                      <label className="form-label">
                        TRAINING PROGRAM
                      </label>

                      <select
                        className="form-select"
                        value={program}
                        onChange={(event) =>
                          setProgram(event.target.value)
                        }
                        required
                      >
                        <option value="">
                          Choose a program
                        </option>

                        <option value="Strength Training">
                          Strength Training
                        </option>

                        <option value="Weight Loss">
                          Weight Loss
                        </option>

                        <option value="Muscle Building">
                          Muscle Building
                        </option>

                        <option value="Cardio Fitness">
                          Cardio Fitness
                        </option>
                      </select>
                    </div>

                    <div className="mb-4">
                      <label className="form-label">
                        PREFERRED TRAINER
                      </label>

                      <select
                        className="form-select"
                        value={trainer}
                        onChange={(event) =>
                          setTrainer(event.target.value)
                        }
                        required
                      >
                        <option value="">
                          Choose a trainer
                        </option>

                        <option value="Any Trainer">
                          Any Trainer
                        </option>

                        <option value="Personal Trainer">
                          Personal Trainer
                        </option>
                      </select>
                    </div>

                    <button
                      type="submit"
                      className="btn btn-forge-dark w-100 subscribe-submit"
                    >
                      CONFIRM SUBSCRIPTION
                    </button>

                    <p className="subscribe-note">
                      Demo only: no real payment is taken.
                    </p>

                  </form>
                </div>
              </div>
              {/* END: Subscription Form */}

              {/* START: Membership Plans */}
              <div className="col-lg-5">
                <div className="subscribe-plans">

                  <p className="subscribe-label">
                    CHOOSE YOUR PLAN
                  </p>

                  {plans.map((plan) => (
                    <div
                      key={plan.name}
                      className={
                        selectedPlan === plan.name
                          ? 'subscribe-plan active'
                          : 'subscribe-plan'
                      }
                    >
                      <div className="subscribe-plan-header">

                        <div>
                          <h3>{plan.name}</h3>

                          <p>
                            EGP {plan.price} / month
                          </p>
                        </div>

                        <input
                          type="radio"
                          name="membership"
                          value={plan.name}
                          checked={selectedPlan === plan.name}
                          onChange={() =>
                            setSelectedPlan(plan.name)
                          }
                        />

                      </div>

                      <ul>
                        {plan.features.map((feature, index) => (
                          <li key={index}>
                            <i className="bi bi-check2"></i>
                            {feature}
                          </li>
                        ))}
                      </ul>

                      {selectedPlan === plan.name && (
                        <span className="selected-plan-label">
                          SELECTED PLAN
                        </span>
                      )}
                    </div>
                  ))}

                  <div className="selected-plan-summary">
                    <span>YOUR SELECTION</span>

                    <h3>{currentPlan.name}</h3>

                    <p>
                      EGP {currentPlan.price}
                      <span> / month</span>
                    </p>
                  </div>

                </div>
              </div>
              {/* END: Membership Plans */}

            </div>
          </section>

          <Footer />
        </>
      )}

    </div>
  );
}

export default AllSubscribe;
