
import React from 'react';

function Awhay() {
  return (
    <div className="scroll-reveal">
      {/* WHY CHOOSE US SECTION START */}
      <section
        id="why-section"
        className="section-padding"
        aria-labelledby="why-title"
      >
        <div className="container">
          <div className="section-heading text-center mx-auto">
            <p className="section-eyebrow">Why choose us</p>
            <h2 className="section-title" id="why-title">
              What We Stand For
            </h2>
          </div>

          <div className="row g-4 justify-content-center">
            <div className="col-md-6 col-lg-4">
              <article className="forge-card benefit-card scroll-reveal">
                <span className="benefit-icon">
                  <i className="bi bi-bullseye" aria-hidden="true" />
                </span>
                <h3 className="benefit-title">Train With Purpose</h3>
                <p className="benefit-text">
                  Focused training for your goals.
                </p>
              </article>
            </div>

            <div className="col-md-6 col-lg-4">
              <article className="forge-card benefit-card scroll-reveal">
                <span className="benefit-icon">
                  <i className="bi bi-people" aria-hidden="true" />
                </span>
                <h3 className="benefit-title">
                  A Supportive Community
                </h3>
                <p className="benefit-text">
                  A motivating environment for every member.
                </p>
              </article>
            </div>

            <div className="col-md-6 col-lg-4">
              <article className="forge-card benefit-card scroll-reveal">
                <span className="benefit-icon">
                  <i
                    className="bi bi-graph-up-arrow"
                    aria-hidden="true"
                  />
                </span>
                <h3 className="benefit-title">Progress That Lasts</h3>
                <p className="benefit-text">
                  Build consistent habits and improve over time.
                </p>
              </article>
            </div>
          </div>
        </div>
      </section>
      {/* WHY CHOOSE US SECTION END */}
    </div>
  );
}

export default Awhay;
