import { useState } from 'react';

function Tprograms() {
  const [selectedProgram, setSelectedProgram] = useState(null);
  const [modalVisible, setModalVisible] = useState(false);

  const programs = [
    {
      title: 'Strength Training',
      level: 'All Levels',
      image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=800&q=70',
      description: 'Build muscle, improve strength, and develop proper lifting technique.',
      details: 'Strength training centres on progressive resistance work with coach guidance. You learn the main lifts with proper technique, then follow a plan that gradually increases the challenge as you get stronger.',
      benefits: [
        'Learn safe, effective lifting technique',
        'Follow a clear, progressive plan',
        'Suitable for beginners through experienced lifters'
      ]
    },
    {
      title: 'Weight Loss',
      level: 'Beginner Friendly',
      image: 'https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=800&q=70',
      description: 'Improve fitness, burn calories, and build sustainable workout habits.',
      details: 'A beginner-friendly mix of cardio, strength work and simple habit building. The focus is on a routine you can keep up over time, not on quick fixes.',
      benefits: [
        'Balanced cardio and strength sessions',
        'Realistic goals and routines you can sustain',
        'A supportive, beginner-friendly pace'
      ]
    },
    {
      title: 'HIIT Training',
      level: 'Intermediate',
      image: 'https://images.unsplash.com/photo-1476480862126-209bfaa8edc8?auto=format&fit=crop&w=800&q=70',
      description: 'Short, intense workouts designed to challenge endurance and conditioning.',
      details: 'High-intensity interval training alternates short bursts of hard effort with recovery. Each session challenges your endurance and conditioning.',
      benefits: [
        'Time-efficient sessions',
        'Challenges endurance and conditioning',
        'Intensity can be adjusted to your level'
      ]
    },
    {
      title: 'Bodybuilding',
      level: 'Intermediate to Advanced',
      image: 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=800&q=70',
      description: 'Build muscle mass through structured resistance training.',
      details: 'Structured resistance training aimed at building muscle mass, with attention to exercise selection, training volume and recovery.',
      benefits: [
        'Structured training plans',
        'Focus on free weights and resistance exercises',
        'Guidance on progression and recovery'
      ]
    },
    {
      title: 'Functional Fitness',
      level: 'All Levels',
      image: 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?auto=format&fit=crop&w=800&q=70',
      description: 'Improve mobility, balance, coordination, and everyday movement.',
      details: 'Movement-focused training that develops mobility, balance and coordination using gym equipment and bodyweight exercises.',
      benefits: [
        'Work on mobility and balance',
        'Train everyday movements',
        'Welcoming to all fitness levels'
      ]
    },
    {
      title: 'Personal Training',
      level: 'Personalized',
      image: 'https://images.unsplash.com/photo-1571902943202-507ec2618e8f?auto=format&fit=crop&w=800&q=70',
      description: 'Individual coaching tailored to personal goals, fitness level, and progress.',
      details: 'One-to-one coaching built around your goals, your current fitness level and your progress.',
      benefits: [
        'A plan tailored to you',
        'Individual attention and feedback',
        'Progress reviewed over time'
      ]
    }
  ];

  function openModal(program) {
    setSelectedProgram(program);

    // Allow the modal to render before starting the animation.
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        setModalVisible(true);
      });
    });
  }

  function closeModal() {
    setModalVisible(false);

    // Wait for the closing animation before removing the modal.
    setTimeout(() => {
      setSelectedProgram(null);
    }, 300);
  }

  return (
    <div className="programs-page">
      <section
        id="programs-section"
        className="section-padding"
        aria-labelledby="programs-title"
      >
        <div className="container">
          <div className="section-heading text-center mx-auto">
            <p className="section-eyebrow">Programs</p>

            <h2 className="section-title" id="programs-title">
              Our Training Programs
            </h2>

            <p className="section-subtitle">
              Six programs for different goals and fitness levels. Open any card to see the full details.
            </p>
          </div>

          <div className="row g-4" id="programsGrid">
            {programs.map((program) => (
              <div className="col-md-6 col-lg-4" key={program.title}>
                <article className="forge-card program-tile">
                  <div className="program-tile-media">
                    <img
                      src={program.image}
                      alt={program.title}
                      className="img-fallback"
                      loading="lazy"
                    />

                    <span className="program-level">
                      {program.level}
                    </span>
                  </div>

                  <div className="program-tile-body">
                    <h3 className="program-tile-title">
                      {program.title}
                    </h3>

                    <p className="program-tile-text">
                      {program.description}
                    </p>

                    <button
                      type="button"
                      className="btn btn-forge-outline btn-forge-sm"
                      onClick={() => openModal(program)}
                    >
                      LEARN MORE
                    </button>
                  </div>
                </article>
              </div>
            ))}
          </div>

          <p className="section-note">
            Program descriptions are illustrative placeholders for a university project.
          </p>
        </div>
      </section>

      {selectedProgram && (
        <>
          <div
            className={`modal fade ${modalVisible ? 'show' : ''}`}
            style={{
              display: 'block',
              pointerEvents: modalVisible ? 'auto' : 'none'
            }}
            tabIndex="-1"
            role="dialog"
            aria-modal="true"
            aria-labelledby="programModalTitle"
            onClick={(event) => {
              if (event.target === event.currentTarget) {
                closeModal();
              }
            }}
          >
            <div className="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable">
              <div className="modal-content program-modal">
                <div className="modal-header">
                  <h2
                    className="modal-title"
                    id="programModalTitle"
                  >
                    {selectedProgram.title}
                  </h2>

                  <button
                    type="button"
                    className="btn-close"
                    aria-label="Close"
                    onClick={closeModal}
                  />
                </div>

                <div className="modal-body">
                  <div className="row g-4">
                    <div className="col-md-5">
                      <div className="program-modal-media">
                        <img
                          src={selectedProgram.image}
                          alt={selectedProgram.title}
                        />
                      </div>
                    </div>

                    <div className="col-md-7">
                      <p className="program-modal-level">
                        Level: {selectedProgram.level}
                      </p>

                      <p>{selectedProgram.details}</p>

                      <h3 className="program-modal-subtitle">
                        Main benefits
                      </h3>

                      <ul className="program-benefits">
                        {selectedProgram.benefits.map((benefit) => (
                          <li key={benefit}>
                            <i
                              className="bi bi-check2"
                              aria-hidden="true"
                            />
                            {benefit}
                          </li>
                        ))}
                      </ul>
                    </div>
                  </div>
                </div>

                <div className="modal-footer">
                  <button
                    type="button"
                    className="btn btn-forge-outline btn-forge-sm"
                    onClick={closeModal}
                  >
                    CLOSE
                  </button>

                  <a
                    className="btn btn-forge-dark btn-forge-sm"
                    href="/memberships"
                  >
                    VIEW MEMBERSHIPS
                  </a>
                </div>
              </div>
            </div>
          </div>

          <div
            className={`modal-backdrop fade ${modalVisible ? 'show' : ''}`}
            onClick={closeModal}
          />
        </>
      )}
    </div>
  );
}

export default Tprograms;