import React from 'react'
import {Link} from 'react-router-dom'
function Footer() {
  return (
    <div>
        <>
  {/* ===== FOOTER SECTION START ===== */}
  <footer id="footer-section" className="site-footer">
    <div className="container">
      <div className="row g-5">
        <div className="col-lg-4">
          <a className="footer-brand" href="home.html">
            FORGE FITNESS
          </a>
          <p className="footer-tagline">
            Built by discipline. Your goals. Your strength. Your next level.
          </p>
        </div>
        <div className="col-6 col-lg-2">
          <h2 className="footer-title">Quick Links</h2>
          <ul className="footer-links">
            <li>
              <Link to="/">Home</Link>
            </li>
            <li>
              <Link to="/programs">Programs</Link>
            </li>
            <li>
              <Link to="/Trainers">Trainers</Link>
            </li>
            <li>
              <Link to="/Memberships">Memberships</Link>
            </li>
            <li>
              <Link to="/Products">Products</Link>
            </li>
            <li>
              <Link to="/About">About Us</Link>
            </li>
            
            <li>
              <Link to="/cart">Cart</Link>
            </li>
          </ul>
        </div>
        <div className="col-6 col-lg-3">
          <h2 className="footer-title">Contact</h2>
          <ul className="footer-contact">
            <li>
              <i className="bi bi-geo-alt" aria-hidden="true" />
              123 Placeholder Street, City
            </li>
            <li>
              <i className="bi bi-envelope" aria-hidden="true" />
              info@forgefitness.example
            </li>
            <li>
              <i className="bi bi-telephone" aria-hidden="true" />
              +00 000 000 0000
            </li>
          </ul>
        </div>
        <div className="col-12 col-lg-3">
          <h2 className="footer-title">Follow Us</h2>
          <div className="footer-social">
            <a
              href="#"
              aria-label="Instagram (placeholder)"
              title="Placeholder link"
            >
              <i className="bi bi-instagram" aria-hidden="true" />
            </a>
            <a
              href="#"
              aria-label="Facebook (placeholder)"
              title="Placeholder link"
            >
              <i className="bi bi-facebook" aria-hidden="true" />
            </a>
            <a href="#" aria-label="X (placeholder)" title="Placeholder link">
              <i className="bi bi-twitter-x" aria-hidden="true" />
            </a>
            <a
              href="#"
              aria-label="YouTube (placeholder)"
              title="Placeholder link"
            >
              <i className="bi bi-youtube" aria-hidden="true" />
            </a>
          </div>
        </div>
      </div>
      <div className="footer-bottom">
        <p className="mb-0">
          © 2026 FORGE FITNESS. University project demo. Contact details and
          social links are placeholders.
        </p>
      </div>
    </div>
  </footer>
  {/* ===== FOOTER SECTION END ===== */}
</>

    </div>
  )
}

export default Footer