
import React from 'react';
import { Link, NavLink } from 'react-router-dom';
import { useCart } from 'react-use-cart';

function Navbar() {
  const { totalItems } = useCart();

  return (
    <>
      {/* ===== NAVBAR SECTION START ===== */}
      <header id="navbar-section">
        <nav
          className="navbar navbar-expand-lg site-navbar"
          aria-label="Main navigation"
        >
          <div className="container">
            <Link
              className="navbar-brand"
              to="/"
              aria-label="FORGE FITNESS home"
            >
              FORGE
              <span className="navbar-brand-sub">FITNESS</span>
            </Link>

            <button
              className="navbar-toggler"
              type="button"
              data-bs-toggle="collapse"
              data-bs-target="#mainNavbar"
              aria-controls="mainNavbar"
              aria-expanded="false"
              aria-label="Toggle navigation"
            >
              <span className="navbar-toggler-icon"></span>
            </button>

            <div className="collapse navbar-collapse" id="mainNavbar">
              <ul className="navbar-nav me-auto">
                <li className="nav-item">
                  <NavLink className="nav-link" to="/" end>
                    Home
                  </NavLink>
                </li>

                <li className="nav-item">
                  <NavLink className="nav-link" to="/programs">
                    Programs
                  </NavLink>
                </li>

                <li className="nav-item">
                  <NavLink className="nav-link" to="/Trainers">
                    Trainers
                  </NavLink>
                </li>

                <li className="nav-item">
                  <NavLink className="nav-link" to="/Memberships">
                    Memberships
                  </NavLink>
                </li>

                <li className="nav-item">
                  <NavLink className="nav-link" to="/Products">
                    Products
                  </NavLink>
                </li>

                <li className="nav-item">
                  <NavLink className="nav-link" to="/About">
                    About Us
                  </NavLink>
                </li>
              </ul>

              <div className="navbar-actions">
                <Link
                  className="nav-cart"
                  to="/cart"
                  aria-label={`Shopping cart, ${totalItems} items`}
                >
                  <i className="bi bi-cart3" aria-hidden="true"></i>

                  {totalItems > 0 && (
                    <span
                      className="nav-cart-count"
                      aria-live="polite"
                    >
                      {totalItems > 99 ? '99+' : totalItems}
                    </span>
                  )}
                </Link>

                <Link
                  className="btn btn-forge-dark btn-forge-sm"
                  to="/Subscribe"
                >
                  JOIN NOW
                </Link>
              </div>
            </div>
          </div>
        </nav>
      </header>
      {/* ===== NAVBAR SECTION END ===== */}
    </>
  );
}

export default Navbar;
