import React from 'react'
import Navbar from '../Components/Navbar'
import Footer from '../Components/Footer'
import Hprogarm from './Hprogarm'
import Tprogram from './Tprograms'
import Bprog from './Bprog'
import Cporg from './Cprog'
import Dprog from './Dprog'



function AllPrograms() {
  return (
    <div  className="programs-page">
        <Navbar></Navbar>
        <Hprogarm></Hprogarm>
        <Tprogram></Tprogram>
        <Bprog></Bprog>
        <Cporg></Cporg>
        <Dprog></Dprog>
        <Footer></Footer>
    </div>

  )
}

export default AllPrograms