
import React, { useEffect, useState } from 'react';
import { CartProvider, useCart } from 'react-use-cart';
import Navbar from '../Components/Navbar';
import Footer from '../Components/Footer';

function Cart() {
  const {
    items,
    updateItemQuantity,
    removeItem,
    totalItems,
    cartTotal,
    emptyCart,
    isEmpty,
  } = useCart();

  const [orderPlaced, setOrderPlaced] = useState(false);
  const [orderDetails, setOrderDetails] = useState(null);

  const formatPrice = (price) =>
    `$${Number(price || 0).toFixed(2)}`;

  useEffect(() => {
    if (!orderPlaced) return;

    const timer = setTimeout(() => {
      window.location.href = '/';
    }, 2500);

    return () => clearTimeout(timer);
  }, [orderPlaced]);

  function handleCheckout() {
    if (isEmpty) return;

    setOrderDetails({
      total: cartTotal,
      quantity: totalItems,
    });

    setOrderPlaced(true);
    emptyCart();
  }

  if (orderPlaced && orderDetails) {
    return (
      <section className="order-success">
        <div className="success-card">
          <div className="success-icon">
            <i className="bi bi-check-lg" aria-hidden="true"></i>
          </div>

          <p className="success-eyebrow">FORGE FITNESS STORE</p>

          <h1>ORDER CONFIRMED</h1>

          <p className="success-message">
            Great choice! Your demo order has been placed successfully.
            Keep pushing your limits.
          </p>

          <div className="success-details">
            <div>
              <span>ITEMS</span>
              <strong>{orderDetails.quantity}</strong>
            </div>

            <div>
              <span>ORDER TOTAL</span>
              <strong>{formatPrice(orderDetails.total)}</strong>
            </div>
          </div>

          <p className="success-note">
            Demo order only — no real payment was processed.
          </p>

          <div className="success-loading">
            <span></span>
          </div>

          <p className="redirect-message">
            Taking you back home...
          </p>
        </div>
      </section>
    );
  }

  return (
    <div className="forge-cart-page">

      {/* START CART HEADER */}
      <section id="cart-header" className="cart-header">
        <div className="container">
          <p className="section-eyebrow">CART</p>

          <h1 className="cart-title" id="cartTitle">
            YOUR CART
          </h1>

          <p className="cart-subtitle">
            Review your gear. Get ready to perform.
          </p>

          <p className="cart-count">
            {totalItems} {totalItems === 1 ? 'ITEM' : 'ITEMS'}
          </p>
        </div>
      </section>
      {/* END CART HEADER */}

      {/* START CART CONTENT */}
      <section
        id="cart-section"
        className="cart-section"
        aria-label="Shopping cart"
      >
        <div className="container">
          {isEmpty ? (
            /* START EMPTY CART */
            <div className="cart-empty">
              <i className="bi bi-cart3" aria-hidden="true"></i>

              <p className="section-eyebrow">YOUR SHOPPING BAG</p>

              <h2>Your cart is empty.</h2>

              <p>
                Nothing here yet. Explore our store and find the
                gear that fits your training.
              </p>

              <a href="/Products" className="cart-btn cart-btn-dark">
                EXPLORE PRODUCTS
              </a>
            </div>
          ) : (
            /* END EMPTY CART / START FILLED CART */
            <div className="row g-4 align-items-start">

              {/* START CART ITEMS */}
              <div className="col-lg-8">
                <div className="cart-items-heading">
                  <h2>YOUR ITEMS</h2>

                  <button
                    type="button"
                    className="cart-clear-btn"
                    onClick={emptyCart}
                  >
                    CLEAR CART
                  </button>
                </div>

                <div className="cart-list">
                  {items.map((item) => (
                    <article className="cart-item" key={item.id}>
                      <div className="cart-item-image">
                        <img
                          src={
                            item.image ||
                            item.thumbnail ||
                            item.images?.[0] ||
                            ''
                          }
                          alt={item.name || item.title || 'Product'}
                          onError={(e) => {
                            e.currentTarget.style.visibility = 'hidden';
                          }}
                        />
                      </div>

                      <div className="cart-item-info">
                        <h3>
                          {item.name || item.title || 'Product'}
                        </h3>

                        <p className="cart-item-unit-price">
                          {formatPrice(item.price)} each
                        </p>

                        <div className="cart-item-controls">
                          <div
                            className="cart-quantity"
                            aria-label={`Quantity for ${
                              item.name || item.title || 'product'
                            }`}
                          >
                            <button
                              type="button"
                              aria-label="Decrease quantity"
                              disabled={item.quantity <= 1}
                              onClick={() =>
                                updateItemQuantity(
                                  item.id,
                                  item.quantity - 1
                                )
                              }
                            >
                              −
                            </button>

                            <span aria-live="polite">
                              {item.quantity}
                            </span>

                            <button
                              type="button"
                              aria-label="Increase quantity"
                              onClick={() =>
                                updateItemQuantity(
                                  item.id,
                                  item.quantity + 1
                                )
                              }
                            >
                              +
                            </button>
                          </div>

                          <button
                            type="button"
                            className="cart-remove-btn"
                            onClick={() => removeItem(item.id)}
                          >
                            <i
                              className="bi bi-trash3"
                              aria-hidden="true"
                            ></i>
                            REMOVE
                          </button>
                        </div>
                      </div>

                      <div className="cart-item-total">
                        {formatPrice(item.price * item.quantity)}
                      </div>
                    </article>
                  ))}
                </div>

                <a href="/Products" className="cart-continue-link">
                  <i
                    className="bi bi-arrow-left"
                    aria-hidden="true"
                  ></i>
                  CONTINUE SHOPPING
                </a>
              </div>
              {/* END CART ITEMS */}

              {/* START ORDER SUMMARY */}
              <div className="col-lg-4">
                <aside
                  className="cart-summary"
                  aria-labelledby="cart-summary-title"
                >
                  <h2 id="cart-summary-title">ORDER SUMMARY</h2>

                  <dl className="cart-summary-rows">
                    <div className="cart-summary-row">
                      <dt>Subtotal</dt>
                      <dd>{formatPrice(cartTotal)}</dd>
                    </div>

                    <div className="cart-summary-row">
                      <dt>Shipping</dt>
                      <dd>Free</dd>
                    </div>

                    <div className="cart-summary-row cart-summary-total">
                      <dt>TOTAL</dt>
                      <dd>{formatPrice(cartTotal)}</dd>
                    </div>
                  </dl>

                  <button
                    type="button"
                    className="cart-btn cart-btn-light"
                    onClick={handleCheckout}
                  >
                    COMPLETE ORDER
                    <i
                      className="bi bi-arrow-right"
                      aria-hidden="true"
                    ></i>
                  </button>

                  <a
                    href="/Products"
                    className="cart-btn cart-btn-outline"
                  >
                    CONTINUE SHOPPING
                  </a>

                  <p className="cart-summary-note">
                    Demo store. No real payment is taken.
                  </p>
                </aside>
              </div>
              {/* END ORDER SUMMARY */}

            </div>
          )}
        </div>
      </section>
      {/* END CART CONTENT */}

    </div>
  );
}

function AllCart() {
  return (
    <CartProvider>
      <Navbar />
      <Cart />
      <Footer />
    </CartProvider>
  );
}

export default AllCart;
